# -*- coding: utf-8 -*-
import json, os

def write(tid, title, translator, intro, segs):
    out = {
        "id": tid, "title": title, "translator": translator,
        "mode": "白话直译", "intro": intro,
        "sutraPath": f"sutras/{tid}.json",
        "translations": segs,
    }
    with open(f"data/modern-translation/{tid}.json","w",encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    print("wrote", tid)

